  1	/* ============================================================
  2	   views/config.js — Configuration view coordinator
  3	   Section 4d of the MCP Server Dashboard SPA
  4	   Depends on: API, UI, escapeHtml, showLoading, showError
  5	   Tab modules: config-model-registry.js, config-persona-models.js (load first)
  6	   Exports (global): configDirty — shared mutable object read/written by all
  7	     three tab modules. Companion files must mutate its properties only; never
  8	     reassign configDirty itself (object identity must be preserved so all
  9	     file-level references stay in sync).
 10	   ============================================================ */
 11	
 12	/* ── Module-level state ──────────────────────────────────── */
 13	
 14	var configActiveTab = 'general';
 15	
 16	/* Dirty-tracking: keyed by tab name, true when the tab has unsaved changes.
 17	   Ownership: declared here (config.js). Mutated by all three tab modules:
 18	     - config.js itself          → .general
 19	     - config-model-registry.js  → .modelRegistry
 20	     - config-persona-models.js  → .personaModels
 21	   Object identity is preserved throughout — companion files hold a reference
 22	   to this object and must never reassign configDirty (only mutate its keys). */
 23	var configDirty = {
 24	  general: false,
 25	  personaModels: false,
 26	  modelRegistry: false
 27	};
 28	
 29	/* ── Entry point ─────────────────────────────────────────── */
 30	
 31	function renderConfig(app) {
 32	  showLoading(app);
 33	
 34	  Promise.all([
 35	    API.getConfig(),
 36	    API.getModels ? API.getModels() : Promise.resolve([]),
 37	    API.getPersonas ? API.getPersonas() : Promise.resolve([]),
 38	    API.getAssignments ? API.getAssignments() : Promise.resolve([])
 39	  ]).then(function (results) {
 40	    renderConfigPage(app, results[0], results[1], results[2], results[3]);
 41	  }).catch(function (err) {
 42	    showError(app, 'Failed to load configuration: ' + (err.message || String(err)));
 43	  });
 44	}
 45	
 46	/* ── Page scaffold ───────────────────────────────────────── */
 47	
 48	function renderConfigPage(app, config, models, personas, assignments) {
 49	  /* Reset dirty flags and all tab module state — fresh server data loaded. */
 50	  configDirty.general = configDirty.personaModels = configDirty.modelRegistry = false;
 51	  mrModels = mrOriginal = mrEditingId = null;
 52	  pmModels = pmPersonas = pmAssignments = pmOriginal = null;
 53	  pmIsBuilding = false; pmCollapsed = {}; pmReplaceOpen = false;
 54	
 55	  app.innerHTML =
 56	    '<div class="page-header"><h1>Configuration</h1></div>' +
 57	    '<div class="config-tabs" id="config-tab-bar">' +
 58	      '<button class="config-tab' + (configActiveTab === 'general'       ? ' active' : '') + '" data-tab="general">General</button>' +
 59	      '<button class="config-tab' + (configActiveTab === 'personaModels' ? ' active' : '') + '" data-tab="personaModels">Persona Models</button>' +
 60	      '<button class="config-tab' + (configActiveTab === 'modelRegistry' ? ' active' : '') + '" data-tab="modelRegistry">Model Registry</button>' +
 61	    '</div>' +
 62	    '<div id="config-tab-content"></div>';
 63	
 64	  renderConfigTabContent(config, models, personas, assignments);
 65	
 66	  var tabBar = document.getElementById('config-tab-bar');
 67	  if (tabBar) {
 68	    tabBar.addEventListener('click', function (e) {
 69	      var btn = e.target.closest('button[data-tab]');
 70	      if (!btn) return;
 71	      var tab = btn.getAttribute('data-tab');
 72	      if (tab === configActiveTab) return;
 73	
 74	      /* Unsaved-changes guard */
 75	      if (configDirty[configActiveTab]) {
 76	        if (!confirm('You have unsaved changes. Discard them?')) return;
 77	        configDirty[configActiveTab] = false;
 78	        if (configActiveTab === 'modelRegistry') {
 79	          mrModels = mrOriginal = mrEditingId = null;
 80	        }
 81	        if (configActiveTab === 'personaModels') {
 82	          pmModels = pmPersonas = pmAssignments = pmOriginal = null;
 83	          pmIsBuilding = false; pmCollapsed = {}; pmReplaceOpen = false;
 84	        }
 85	      }
 86	
 87	      configActiveTab = tab;
 88	      tabBar.querySelectorAll('.config-tab').forEach(function (b) {
 89	        b.classList.toggle('active', b.getAttribute('data-tab') === tab);
 90	      });
 91	      renderConfigTabContent(config, models, personas, assignments);
 92	    });
 93	  }
 94	}
 95	
 96	/* ── Tab content dispatcher ──────────────────────────────── */
 97	
 98	function renderConfigTabContent(config, models, personas, assignments) {
 99	  var contentEl = document.getElementById('config-tab-content');
100	  if (!contentEl) return;

101	
102	  if (configActiveTab === 'general') {
103	    contentEl.innerHTML = renderGeneralTab(config);
104	    wireGeneralTabEvents();
105	  } else if (configActiveTab === 'personaModels') {
106	    contentEl.innerHTML = renderPersonaModelsTab(models, personas, assignments);
107	    pmWireEvents();
108	  } else if (configActiveTab === 'modelRegistry') {
109	    contentEl.innerHTML = renderModelRegistryTab(models);
110	    mrWireEvents();
111	  }
112	}
113	
114	/* ── General tab ─────────────────────────────────────────── */
115	
116	function renderGeneralTab(config) {
117	  return UI.card(null,
118	    '<form id="config-form">' +
119	      '<div class="form-group">' +
120	        '<label class="form-label" for="auto-handoff">' +
121	          '<input type="checkbox" id="auto-handoff" class="form-check" ' + (config.auto_handoff_enabled ? 'checked' : '') + '>' +
122	          ' Auto-handoff enabled' +
123	        '</label>' +
124	        '<p class="form-note">When enabled, the MCP server automatically chains work to the next agent in the workflow.</p>' +
125	      '</div>' +
126	      '<div class="form-group">' +
127	        '<label class="form-label" for="max-depth">Max handoff depth</label>' +
128	        '<input type="number" id="max-depth" class="form-control" min="1" value="' + escapeHtml(String(config.max_handoff_depth)) + '">' +
129	        '<p class="form-note">Maximum number of automatic agent handoffs before stopping.</p>' +
130	      '</div>' +
131	      '<div class="form-group">' +
132	        '<label class="form-label" for="capture-dialogues">' +
133	          '<input type="checkbox" id="capture-dialogues" class="form-check" ' + (config.capture_dialogues ? 'checked' : '') + '>' +
134	          ' Capture agent dialogues' +
135	        '</label>' +
136	        '<p class="form-note">When enabled, the orchestrator saves the full LLM conversation for each pipeline stage to the project\'s ledger as Markdown files. Changes take effect on the next orchestrator run.</p>' +
137	      '</div>' +
138	      '<div class="form-group">' +
139	        '<label class="form-label" for="auto-archive-days">Auto-archive after (days)</label>' +
140	        '<input type="number" id="auto-archive-days" class="form-control" min="0" step="1" value="' + escapeHtml(String(config.auto_archive_days != null ? config.auto_archive_days : 6)) + '">' +
141	        '<p class="form-note">Number of days after last update before a COMPLETE project is automatically archived. Set to 0 to disable auto-archiving.</p>' +
142	      '</div>' +
143	      '<div class="form-group">' +
144	        '<label class="form-label" for="ledger-root">Ledger root path</label>' +
145	        '<input type="text" id="ledger-root" class="form-control" readonly value="' + escapeHtml(config.ledger_root || '') + '">' +
146	        '<p class="form-note">Read-only. Changing this requires restarting the server with <code>--ledger-dir</code>.</p>' +
147	      '</div>' +
148	      '<button type="submit" class="btn btn-primary">Save</button>' +
149	      '<div id="config-msg"></div>' +
150	    '</form>',
151	    { style: 'max-width:560px' }
152	  );
153	}
154	
155	function wireGeneralTabEvents() {
156	  var form = document.getElementById('config-form');
157	  if (!form) return;
158	
159	  /* Mark tab dirty on any input change.
160	     Both 'change' and 'input' are intentional: checkboxes fire 'change'
161	     (not 'input'), while text/number inputs fire 'input' on each keystroke. */
162	  form.addEventListener('change', function () { configDirty.general = true; });
163	  form.addEventListener('input',  function () { configDirty.general = true; });
164	
165	  form.addEventListener('submit', function (e) {
166	    e.preventDefault();
167	    var autoHandoff = document.getElementById('auto-handoff').checked;
168	    var maxDepth = parseInt(document.getElementById('max-depth').value, 10);
169	    if (isNaN(maxDepth) || maxDepth < 1) {
170	      showError(document.getElementById('config-msg'), 'Max handoff depth must be a positive integer.');
171	      return;
172	    }
173	    var captureDialogues = document.getElementById('capture-dialogues').checked;
174	    var autoArchiveDays = parseInt(document.getElementById('auto-archive-days').value, 10);
175	    if (isNaN(autoArchiveDays) || autoArchiveDays < 0) {
176	      showError(document.getElementById('config-msg'), 'Auto-archive days must be a non-negative integer.');
177	      return;
178	    }
179	    /* ledger_root intentionally omitted (read-only) */
180	    API.updateConfig({ auto_handoff_enabled: autoHandoff, max_handoff_depth: maxDepth, capture_dialogues: captureDialogues, auto_archive_days: autoArchiveDays })
181	      .then(function () {
182	        configDirty.general = false;
183	        document.getElementById('config-msg').innerHTML = '<p class="success-banner">Configuration saved.</p>';
184	      })
185	      .catch(function (err) {
186	        showError(document.getElementById('config-msg'), 'Save failed: ' + (err.message || String(err)));
187	      });
188	  });
189	}
190	
191

